64 |   async compact(history: Message[]): Promise<{
65 |     isCompacted: boolean,
66 |     summaryMessage: Message | null,
67 |     list: Message[]
68 |   }> {
69 |     const totalUsed = this.calculateTotalUsage(history);
70 |     const usableLimit = this.maxTokens - this.maxOutputTokens;
71 |     const KEEP_RECENT_COUNT = 6;
72 |     // 如果没达到 92% 的阈值，直接返回原数据
73 |     if (totalUsed < usableLimit * this.triggerRatio || history.length <= KEEP_RECENT_COUNT) {
74 |       return {
75 |         isCompacted: false,
76 |         summaryMessage: null,
77 |         list: history
78 |       };
79 |     }
