238 |     private async withTimeout<T>(promise: Promise<T>, timeoutMs: number, timeoutMessage: string): Promise<T> {
239 |         if (!timeoutMs || timeoutMs <= 0) {
240 |             return promise;
241 |         }
242 | 
243 |         let timeoutId: ReturnType<typeof setTimeout> | undefined;
244 |         const timeoutPromise = new Promise<never>((_, reject) => {
245 |             timeoutId = setTimeout(() => reject(new Error(timeoutMessage)), timeoutMs);
246 |         });
247 | 
248 |         return Promise.race([promise, timeoutPromise]).finally(() => {
249 |             if (timeoutId) {
250 |                 clearTimeout(timeoutId);
251 |             }
252 |         });
253 |     }
