255 |     private async runWithConcurrency<T, R>(
256 |         items: T[],
257 |         limit: number,
258 |         task: (item: T, index: number) => Promise<R>
259 |     ): Promise<R[]> {
260 |         if (items.length === 0) {
261 |             return [];
262 |         }
263 | 
264 |         if (limit <= 1) {
265 |             const results: R[] = [];
266 |             for (let i = 0; i < items.length; i++) {
267 |                 results.push(await task(items[i], i));
268 |             }
269 |             return results;
270 |         }
271 | 
272 |         const results = new Array<R>(items.length);
273 |         let nextIndex = 0;
274 |         const workerCount = Math.min(limit, items.length);
275 | 
276 |         const workers = Array.from({ length: workerCount }, async () => {
277 |             while (true) {
278 |                 const currentIndex = nextIndex++;
279 |                 if (currentIndex >= items.length) {
280 |                     break;
281 |                 }
282 |                 results[currentIndex] = await task(items[currentIndex], currentIndex);
283 |             }
284 |         });
285 | 
286 |         await Promise.all(workers);
287 |         return results;
288 |     }
