542 |     private async handleToolCalls(params: {
543 |         toolCalls: ToolCall[];
544 |         content: string;
545 |         iteration: number;
546 |         options?: { silent?: boolean };
547 |         stats: ToolStats;
548 |         progress: { lastToolSignature: string | null; repeatedToolCalls: number };
549 |     }): Promise<{ lastToolSignature: string | null; repeatedToolCalls: number }> {
550 |         const { toolCalls, content, iteration, options, stats, progress } = params;
551 | 
552 |         const toolSignature = this.buildToolSignature(toolCalls);
553 |         if (toolSignature && toolSignature === progress.lastToolSignature) {
554 |             progress.repeatedToolCalls += 1;
555 |         } else {
556 |             progress.repeatedToolCalls = 0;
557 |             progress.lastToolSignature = toolSignature;
558 |         }
559 | 
560 |         if (this.noProgressLimit > 0 && progress.repeatedToolCalls >= this.noProgressLimit) {
561 |             throw new Error(
562 |                 `Repeated tool_calls detected for ${this.noProgressLimit + 1} iterations, aborting to prevent loop.`
563 |             );
564 |         }
565 | 
566 |         await this.recordMessage({
567 |             role: 'assistant',
568 |             content,
569 |             type: 'tool_call',
570 |             tool_calls: toolCalls,
571 |         });
572 | 
573 |         this.logger.info(`Tool tips: ${content}`);
574 | 
575 |         const toolsBatchStartTime = Date.now();
576 |         await this.eventBus.emit('agent.tools.batch.start', {
577 |             toolCalls,
578 |             iteration,
579 |         });
580 | 
581 |         const toolConcurrency = Math.min(this.toolConcurrency, toolCalls.length);
582 |         const results = await this.runWithConcurrency(toolCalls, toolConcurrency, (toolCall) => (
583 |             this.executeToolCall(toolCall, iteration, options, stats)
584 |         ));
585 | 
586 |         for (const { toolCall, result } of results) {
587 |             await this.recordMessage({
588 |                 role: 'tool',
589 |                 content: result,
590 |                 type: 'tool',
591 |                 tool_call_id: toolCall.id,
592 |             });
593 |         }
594 | 
595 |         const toolsBatchDuration = Date.now() - toolsBatchStartTime;
596 |         await this.eventBus.emit('agent.tools.batch.complete', {
597 |             results: results.map(r => ({
598 |                 toolName: r.toolCall.function.name,
599 |                 result: r.result,
600 |                 error: r.error,
601 |             })),
602 |             duration: toolsBatchDuration,
603 |             iteration,
604 |         });
605 | 
606 |         await this.eventBus.emit('agent.loop.complete', {
607 |             iteration,
608 |             hasToolCalls: true,
609 |         });
610 | 
611 |         await this.triggerHook(AgentHook.AFTER_LOOP_ITERATION, {
612 |             iteration,
613 |             hasToolCalls: true,
614 |         });
615 | 
616 |         return { ...progress };
617 |     }
