459 | export class ScopedEventBus {
460 |   constructor(
461 |     private parent: EventBus,
462 |     private scope: string
463 |   ) {}
464 | 
465 |   on<T = any>(event: string, handler: EventHandler<T>, handlerId?: string): Subscription {
466 |     return this.parent.on(this.scopedEvent(event), handler, handlerId);
467 |   }
468 | 
469 |   onAsync<T = any>(event: string, handler: AsyncEventHandler<T>, handlerId?: string): Subscription {
470 |     return this.parent.onAsync(this.scopedEvent(event), handler, handlerId);
471 |   }
472 | 
473 |   once<T = any>(event: string, handler: EventHandler<T>): Subscription {
474 |     return this.parent.once(this.scopedEvent(event), handler);
475 |   }
476 | 
477 |   onceAsync<T = any>(event: string, handler: AsyncEventHandler<T>): Subscription {
478 |     return this.parent.onceAsync(this.scopedEvent(event), handler);
479 |   }
480 | 
481 |   async emit<T = any>(event: string, data: T, metadata: Partial<EventMetadata> = {}): Promise<void> {
482 |     return this.parent.emit(this.scopedEvent(event), data, {
483 |       ...metadata,
484 |       scope: this.scope,
485 |     });
486 |   }
487 | 
488 |   off(event: string, handlerId: string): boolean {
489 |     return this.parent.off(this.scopedEvent(event), handlerId);
490 |   }
491 | 
492 |   offAll(): void {
493 |     // 移除所有属于该作用域的事件
494 |     const events = this.parent.eventNames();
495 |     for (const event of events) {
496 |       if (event.startsWith(`${this.scope}.`)) {
497 |         this.parent.offAll(event);
498 |       }
499 |     }
500 |   }
501 | 
502 |   private scopedEvent(event: string): string {
503 |     return `${this.scope}.${event}`;
504 |   }
